UpdatedDocWithImage.inputs:
@setProperty(
  setProperty(
    setProperty(
      first(outputs('QueryById')?['body']?['value']),
      'imageBlobName',
      concat(triggerOutputs()['queries']['id'], '/', triggerBody()?['fileName'])
    ),
    'imageContentType',
    triggerBody()?['contentType']
  ),
  'updatedAt',
  utcNow()
)
